using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Text;using OpenCvSharp;using SarmatVisionHold.Vision;
namespace SarmatVisionHold.VideoAnalyzer
{
 internal static class Program
 {
  static int Main(string[] args){try{var c=CommandLine.Parse(args);if(c.Help){Usage();return 0;}if(string.IsNullOrWhiteSpace(c.Input)||string.IsNullOrWhiteSpace(c.Output)){Usage();Console.Error.WriteLine("ERROR: --input and --output are required.");return 2;}return Analyze(c);}catch(ArgumentException e){Console.Error.WriteLine("ERROR: "+e.Message);return 2;}catch(Exception e){Console.Error.WriteLine("FATAL: "+e.Message);return 1;}}
  static int Analyze(CommandLine c){var input=Path.GetFullPath(c.Input);var output=Path.GetFullPath(c.Output);if(!File.Exists(input)){Console.Error.WriteLine("ERROR: input video does not exist: "+input);return 3;}Directory.CreateDirectory(output);using(var cap=new VideoCapture(input)){if(!cap.IsOpened()){Console.Error.WriteLine("ERROR: decoder could not open input video.");return 3;}var fps=Positive(cap.Fps,25);var width=(int)cap.FrameWidth;var height=(int)cap.FrameHeight;if(width<=0||height<=0){Console.Error.WriteLine("ERROR: empty/invalid video dimensions.");return 3;}if(c.Start>0)cap.PosMsec=(int)(c.Start*1000);using(var mask=BuildMask(c.Options,width,height))using(var writer=OpenWriter(output,fps,width,height)){if(writer==null){Console.Error.WriteLine("ERROR: annotated video writer unavailable.");return 4;}var rows=new List<Row>();using(var csv=new StreamWriter(Path.Combine(output,"motion.csv"),false,new UTF8Encoding(false)))using(var flow=new SparseOpticalFlowProcessor(c.Options.FlowOptions())){var classifier=new TemporalMotionClassifier(c.Options.ClassifierOptions());csv.WriteLine("timestamp,frame_index,delta_time,raw_translation_x,raw_translation_y,smoothed_translation_x,smoothed_translation_y,raw_rotation_deg,smoothed_rotation_deg,raw_scale,smoothed_scale,raw_class,smoothed_class,texture_motion,estimated_camera_motion,tracked_points,inliers,inlier_ratio,quality,processing_time_ms,status");long index=0;double previous=c.Start;while(true){using(var frame=new Mat()){bool read;try{read=cap.Read(frame);}catch(Exception e){Console.Error.WriteLine($"WARN decoder frame {index}: {e.Message}");break;}if(!read||frame.Empty())break;var timestamp=Safe(cap.PosMsec/1000,c.Start+index/fps);if(index>0&&timestamp<=previous)timestamp=previous+1/fps;if(c.Duration>=0&&timestamp>c.Start+c.Duration)break;var dt=index==0?0:timestamp-previous;previous=timestamp;var sw=Stopwatch.StartNew();SparseOpticalFlowResult result;try{using(var gray=new Mat()){Cv2.CvtColor(frame,gray,ColorConversionCodes.BGR2GRAY);result=flow.Process(gray,mask);}}catch(Exception e){result=new SparseOpticalFlowResult{Status=FlowTrackingStatus.LOST,Reason="Processing error: "+e.GetType().Name};Console.Error.WriteLine($"WARN frame {index}: {e.Message}");}if(result.Quality<c.Options.MinimumQuality&&result.Status==FlowTrackingStatus.OK)result.Status=FlowTrackingStatus.DEGRADED;var decision=classifier.Update(result);sw.Stop();var row=Row.From(timestamp,index,dt,result,decision,sw.Elapsed.TotalMilliseconds);rows.Add(row);WriteCsv(csv,row);Annotate(frame,result,row);writer.Write(frame);if(c.Preview){Cv2.ImShow("Sarmat Vision Hold motion detector",frame);var key=Cv2.WaitKey(1);if(key==27||key=='q')break;}index++;}}if(c.Preview)Cv2.DestroyAllWindows();if(rows.Count==0){Console.Error.WriteLine("ERROR: selected interval has no decodable frames.");return 3;}var labels=string.IsNullOrWhiteSpace(c.Labels)?new List<Label>():ReadLabels(c.Labels);WriteReport(Path.Combine(output,"report.md"),input,width,height,fps,rows,labels);Console.WriteLine($"Analyzed {rows.Count} frames. Results: {output}");return 0;}}}}
  static Mat BuildMask(AnalyzerOptions o,int w,int h){Mat mask=null;if(!string.IsNullOrWhiteSpace(o.MaskPath)){var p=Path.GetFullPath(o.MaskPath);mask=Cv2.ImRead(p,ImreadModes.Grayscale);if(mask.Empty()||mask.Width!=w||mask.Height!=h){mask.Dispose();throw new ArgumentException("Mask must be readable and match video dimensions.");}Cv2.Threshold(mask,mask,0,255,ThresholdTypes.Binary);}if(o.RoiWidth>0&&o.RoiHeight>0){int x=Math.Max(0,o.RoiX);int y=Math.Max(0,o.RoiY);int rw=Math.Min(o.RoiWidth,w-x);int rh=Math.Min(o.RoiHeight,h-y);if(rw<=0||rh<=0){mask?.Dispose();throw new ArgumentException("ROI is outside frame.");}using(var roi=new Mat(h,w,MatType.CV_8UC1,Scalar.Black)){Cv2.Rectangle(roi,new Rect(x,y,rw,rh),Scalar.White,-1);if(mask==null)mask=roi.Clone();else Cv2.BitwiseAnd(mask,roi,mask);}}return mask;}
  static VideoWriter OpenWriter(string output,double fps,int w,int h){var mkv=new VideoWriter(Path.Combine(output,"annotated.mkv"),FourCC.XVID,fps,new Size(w,h));if(mkv.IsOpened())return mkv;mkv.Dispose();var mp4=new VideoWriter(Path.Combine(output,"annotated.mp4"),FourCC.MP4V,fps,new Size(w,h));if(mp4.IsOpened())return mp4;mp4.Dispose();return null;}
  static void Annotate(Mat frame,SparseOpticalFlowResult r,Row row){foreach(var t in r.Tracks){var color=t.Accepted?Scalar.LimeGreen:Scalar.Red;Cv2.Circle(frame,(Point)t.From,t.Accepted?3:2,color,-1,LineTypes.AntiAlias);if(t.ForwardTracked)Cv2.ArrowedLine(frame,(Point)t.From,(Point)t.To,color,1,LineTypes.AntiAlias,0,.2);}var center=new Point(frame.Width/2,frame.Height/2);Cv2.ArrowedLine(frame,center,new Point(center.X+(int)(r.TranslationX*15),center.Y+(int)(r.TranslationY*15)),Scalar.Yellow,4,LineTypes.AntiAlias,0,.3);Cv2.Rectangle(frame,new Rect(0,0,Math.Min(frame.Width,1100),94),Scalar.Black,-1);var colorStatus=r.Status==FlowTrackingStatus.OK?Scalar.LimeGreen:r.Status==FlowTrackingStatus.DEGRADED?Scalar.Orange:Scalar.Red;Cv2.PutText(frame,$"Texture motion: {row.Texture}    Estimated camera motion: {row.Camera}",new Point(10,24),HersheyFonts.HersheySimplex,.58,colorStatus,2);Cv2.PutText(frame,$"Class: {row.SmoothClass}  T=({r.TranslationX:F2},{r.TranslationY:F2}) px/f  R={r.RotationDegrees:F3} deg/f  scale={r.Scale:F5}",new Point(10,52),HersheyFonts.HersheySimplex,.55,colorStatus,2);Cv2.PutText(frame,$"tracked={r.TrackedPoints} inliers={r.InlierCount} ratio={r.InlierRatio:F2} quality={r.Quality:F2} {r.Status}",new Point(10,80),HersheyFonts.HersheySimplex,.55,colorStatus,2);}
  static void WriteCsv(StreamWriter w,Row r)=>w.WriteLine(string.Join(",",F(r.Time),r.Index,F(r.Dt),F(r.RawX),F(r.RawY),F(r.X),F(r.Y),F(r.RawRotation),F(r.Rotation),F(r.RawScale),F(r.Scale),r.RawClass,r.SmoothClass,r.Texture,r.Camera,r.Tracked,r.Inliers,F(r.InlierRatio),F(r.Quality),F(r.ProcessingMs),r.Status));
  static List<Label> ReadLabels(string path){var result=new List<Label>();var full=Path.GetFullPath(path);if(!File.Exists(full))throw new ArgumentException("Labels file not found: "+full);foreach(var line in File.ReadAllLines(full)){if(string.IsNullOrWhiteSpace(line)||line.TrimStart().StartsWith("#")||line.StartsWith("start",StringComparison.OrdinalIgnoreCase))continue;var p=line.Split(',');if(p.Length<3)throw new ArgumentException("Invalid labels.csv row: "+line);result.Add(new Label{Start=double.Parse(p[0],CultureInfo.InvariantCulture),End=double.Parse(p[1],CultureInfo.InvariantCulture),Expected=Normalize(p[2])});}return result;}
  static void WriteReport(string path,string input,int w,int h,double fps,List<Row> rows,List<Label> labels){var mags=rows.Select(x=>Math.Sqrt(x.RawX*x.RawX+x.RawY*x.RawY)).OrderBy(x=>x).ToArray();var jumps=rows.Skip(1).Select((x,i)=>new{Time=x.Time,Jump=Math.Sqrt(Sq(x.RawX-rows[i].RawX)+Sq(x.RawY-rows[i].RawY))+Math.Abs(x.RawRotation-rows[i].RawRotation)}).OrderByDescending(x=>x.Jump).Take(10);var low=Intervals(rows,x=>x.Status!="OK");using(var wr=new StreamWriter(path,false,new UTF8Encoding(false))){wr.WriteLine("# Mixed-video texture motion report\n");wr.WriteLine($"- Input: `{input}`\n- Interval: {rows.First().Time:F3}–{rows.Last().Time:F3} s\n- Resolution: {w}×{h}\n- FPS: {fps:F3}\n- Frames: {rows.Count}\n- Mean processing: {rows.Average(x=>x.ProcessingMs):F3} ms/frame\n- Mean/min quality: {rows.Average(x=>x.Quality):F4}/{rows.Min(x=>x.Quality):F4}\n- Median/P95 translation magnitude: {Pct(mags,.5):F4}/{Pct(mags,.95):F4} px/frame\n");foreach(var bucket in new[]{"STILL","TRANSLATING","ROTATING","MIXED","DEGRADED","LOST"})wr.WriteLine($"- {bucket}: {rows.Count(x=>Bucket(x)==bucket)*100d/rows.Count:F2}%");wr.WriteLine("\n## Largest jumps\n\n| Time | Combined jump |\n|---:|---:|");foreach(var j in jumps)wr.WriteLine($"| {j.Time:F3} | {j.Jump:F4} |");wr.WriteLine("\n## Low-quality intervals\n\n| Start | End |\n|---:|---:|");foreach(var v in low)wr.WriteLine($"| {v.Item1:F3} | {v.Item2:F3} |");if(labels.Count>0)WriteValidation(wr,rows,labels);}}
  static void WriteValidation(StreamWriter w,List<Row> rows,List<Label> labels){var pairs=new List<Tuple<string,string>>();var errors=new List<string>();foreach(var l in labels){var selected=rows.Where(x=>x.Time>=l.Start&&x.Time<=l.End).ToList();if(selected.Count==0){errors.Add($"{l.Start:F3}–{l.End:F3}: no analyzed frames");continue;}var correct=selected.Count(x=>Normalize(x.SmoothClass)==l.Expected);if(correct<selected.Count)errors.Add($"{l.Start:F3}–{l.End:F3} expected {l.Expected}: {correct}/{selected.Count} correct");pairs.AddRange(selected.Select(x=>Tuple.Create(l.Expected,Normalize(x.SmoothClass))));}w.WriteLine("\n## Manual validation\n");w.WriteLine($"Accuracy: {(pairs.Count==0?0:pairs.Count(x=>x.Item1==x.Item2)*100d/pairs.Count):F2}% ({pairs.Count(x=>x.Item1==x.Item2)}/{pairs.Count})\n");var classes=pairs.SelectMany(x=>new[]{x.Item1,x.Item2}).Distinct().OrderBy(x=>x).ToArray();w.Write("| Expected \\ Predicted |");foreach(var c in classes)w.Write(c+"|");w.WriteLine("\n|---|"+string.Join("",classes.Select(x=>"---:|")));foreach(var e in classes){w.Write("| "+e+" |");foreach(var p in classes)w.Write(pairs.Count(x=>x.Item1==e&&x.Item2==p)+"|");w.WriteLine();}w.WriteLine("\n### Mislabeled intervals\n");if(errors.Count==0)w.WriteLine("None.");else foreach(var e in errors)w.WriteLine("- "+e);}
  static List<Tuple<double,double>> Intervals(List<Row> rows,Func<Row,bool> predicate){var result=new List<Tuple<double,double>>();double? start=null,last=null;foreach(var r in rows){if(predicate(r)){if(!start.HasValue)start=r.Time;last=r.Time;}else if(start.HasValue){result.Add(Tuple.Create(start.Value,last.Value));start=last=null;}}if(start.HasValue)result.Add(Tuple.Create(start.Value,last.Value));return result;}
  static string Bucket(Row r){if(r.Status=="DEGRADED"||r.Status=="LOST")return r.Status;if(r.SmoothClass.StartsWith("TRANSLATING"))return "TRANSLATING";if(r.SmoothClass.StartsWith("ROTATING"))return "ROTATING";if(r.SmoothClass=="STILL")return "STILL";return "MIXED";}static string Normalize(string s){s=(s??"").Trim().ToUpperInvariant().Replace(' ','_');if(s.StartsWith("TRANSLATING_"))s=s.Substring(12);return s;}
  static double Pct(double[] a,double p){if(a.Length==0)return 0;double pos=(a.Length-1)*p;int lo=(int)pos;int hi=(int)Math.Ceiling(pos);return a[lo]+(a[hi]-a[lo])*(pos-lo);}static double Positive(double v,double d)=>Finite(v)&&v>0?v:d;static double Safe(double v,double d)=>Finite(v)&&v>=0?v:d;static bool Finite(double v)=>!double.IsNaN(v)&&!double.IsInfinity(v);static double Sq(double v)=>v*v;static string F(double v)=>(Finite(v)?v:0).ToString("0.########",CultureInfo.InvariantCulture);
  static void Usage()=>Console.WriteLine("SarmatVisionHold.VideoAnalyzer --input <video> --output <dir> [--preview] [--start sec] [--duration sec] [--roi x,y,w,h] [--mask file] [--labels labels.csv] [--config json] [--minimum-quality N] [--translation-threshold px] [--rotation-threshold deg] [--scale-threshold N] [--ransac-threshold px] [--ransac-confidence N] [--ransac-iterations N]");
  sealed class Row{public double Time,Dt,RawX,RawY,X,Y,RawRotation,Rotation,RawScale,Scale,InlierRatio,Quality,ProcessingMs;public long Index;public int Tracked,Inliers;public string RawClass,SmoothClass,Texture,Camera,Status;public static Row From(double time,long index,double dt,SparseOpticalFlowResult f,MotionDecision d,double ms)=>new Row{Time=time,Index=index,Dt=dt,RawX=f.TranslationX,RawY=f.TranslationY,X=d.SmoothedX,Y=d.SmoothedY,RawRotation=f.RotationDegrees,Rotation=d.SmoothedRotation,RawScale=f.Scale,Scale=d.SmoothedScale,RawClass=d.RawClass,SmoothClass=d.SmoothedClass,Texture=d.TextureMotion,Camera=d.EstimatedCameraMotion,Tracked=f.TrackedPoints,Inliers=f.InlierCount,InlierRatio=f.InlierRatio,Quality=f.Quality,ProcessingMs=ms,Status=f.Status.ToString()};}
  sealed class Label{public double Start,End;public string Expected;}
 }
}
